// Valida e organiza o lead que chega do formulário da LP (assets/js/app.js → montaLead).
// Saída: valido/erro, dados do e-mail, linha da planilha e dados prontos para o CRM.
const txt = (v, max = 200) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const num = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const digitos = (v) => String(v ?? '').replace(/\D/g, '');
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return $input.all().map((item) => {
  let b = item.json.body ?? {};
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch { b = {}; } }

  const lead = {
    nome: txt(b.nome, 120),
    tipo: b.tipo_pessoa === 'PJ' ? 'PJ' : 'PF',
    cnpj: txt(b.cnpj, 20),
    razao: txt(b.razao_social, 150),
    cidade: txt(b.cidade, 80),
    telefone: txt(b.telefone, 30),
    email: txt(b.email, 150).toLowerCase(),
    perfil: txt(b.perfil, 40),
    mensagem: String(b.mensagem ?? '').trim().slice(0, 1000),
    pagina: txt(b.pagina, 500),
    utm: Object.fromEntries(['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid'].map((k) => [k, txt(b[k], 200)])),
  };

  const produtos = (Array.isArray(b.produtos) ? b.produtos : []).slice(0, 50).map((p) => {
    const porUnidade = Number(p.metragem_por_unidade_m) || Number(digitos(p.metragem_m)) || 0;
    const quantidade = Number(p.quantidade) || 1;
    const ac = p.acondicionamento || {};
    return {
      bitola: txt(p.bitola_mm2, 10),
      cor: txt(p.cor, 30),
      quantidade,
      porUnidade,
      total: Number(p.metragem_total_m) || porUnidade * quantidade,
      padrao: txt(ac.padrao, 30),
      solicitado: txt(ac.solicitado, 30),
      analise: Boolean(ac.analise),
    };
  });

  const erros = [];
  if (!lead.nome) erros.push('nome');
  if (digitos(lead.telefone).length < 10) erros.push('telefone');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.email)) erros.push('email');
  if (lead.tipo === 'PJ' && digitos(lead.cnpj).length !== 14) erros.push('cnpj');
  if (!produtos.length) erros.push('produtos');
  if (erros.length) return { json: { valido: false, erro: `Campos inválidos: ${erros.join(', ')}` } };

  const metragemTotal = produtos.reduce((s, p) => s + p.total, 0);
  const temAnalise = produtos.some((p) => p.analise);
  const embalagem = (p) => [p.padrao ? `${p.padrao} (padrão)` : 'sem padrão', p.solicitado ? `solicitado: ${p.solicitado}` : '', p.analise ? 'ANÁLISE COMERCIAL' : ''].filter(Boolean).join(' · ');
  const linhaProduto = (p) => `${p.bitola} mm² · ${p.cor} · ${num(p.quantidade)} × ${num(p.porUnidade)} m = ${num(p.total)} m · ${embalagem(p)}`;
  const origem = [lead.utm.utm_source, lead.utm.utm_medium, lead.utm.utm_campaign].filter(Boolean).join(' / ') || (lead.utm.gclid ? 'Google Ads' : lead.utm.fbclid ? 'Meta Ads' : 'Direto');

  const dadosCliente = [
    ['Nome', lead.nome],
    ['Tipo', lead.tipo === 'PJ' ? 'Pessoa jurídica' : 'Pessoa física'],
    lead.tipo === 'PJ' ? ['CNPJ', lead.cnpj + (lead.razao ? ` — ${lead.razao}` : '')] : null,
    lead.cidade ? ['Cidade', lead.cidade] : null,
    ['Telefone', lead.telefone],
    ['E-mail', lead.email],
    ['Perfil', lead.perfil],
    ['Origem', origem],
    ['Recebido em', agora],
  ].filter(Boolean);

  const td = 'padding:6px 10px;border:1px solid #dde3ea;font-size:14px;vertical-align:top';
  const html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#10233D;max-width:720px">
<h2 style="margin:0 0 4px;color:#F08000">Novo pedido de cotação — LP New Cabos</h2>
<p style="margin:0 0 16px;font-size:13px;color:#555">Para responder ao cliente, use “Responder”: o e-mail vai direto para ${esc(lead.email)}.</p>
<table style="border-collapse:collapse;margin-bottom:16px">${dadosCliente.map(([k, v]) => `<tr><th style="${td};text-align:left;background:#f4f7fa">${esc(k)}</th><td style="${td}">${esc(v)}</td></tr>`).join('')}</table>
<h3 style="margin:0 0 8px">Produtos (${produtos.length}) · total ${num(metragemTotal)} m</h3>
<table style="border-collapse:collapse;margin-bottom:16px"><tr>${['Bitola', 'Cor', 'Qtd.', 'm/unid.', 'Total', 'Acondicionamento'].map((h) => `<th style="${td};background:#10233D;color:#fff;text-align:left">${h}</th>`).join('')}</tr>
${produtos.map((p) => `<tr><td style="${td}">${esc(p.bitola)} mm²</td><td style="${td}">${esc(p.cor)}</td><td style="${td}">${num(p.quantidade)}</td><td style="${td}">${num(p.porUnidade)} m</td><td style="${td}">${num(p.total)} m</td><td style="${td}">${esc(embalagem(p))}</td></tr>`).join('\n')}</table>
${temAnalise ? '<p style="padding:8px 12px;background:#FFF4E0;border-left:4px solid #F5A11E;font-size:14px">Há item que exige análise comercial e produtiva (metragem fora do padrão, 16 mm² ou embalagem diferente da padrão).</p>' : ''}
${lead.mensagem ? `<h3 style="margin:16px 0 8px">Sobre a obra/pedido</h3><p style="white-space:pre-wrap;font-size:14px;margin:0">${esc(lead.mensagem)}</p>` : ''}
<p style="margin-top:24px;font-size:12px;color:#888">Página: ${esc(lead.pagina)}</p>
</div>`;

  const resumo = [
    `Nome: ${lead.nome}`,
    `Tipo: ${lead.tipo}${lead.tipo === 'PJ' ? ` · CNPJ ${lead.cnpj}${lead.razao ? ` — ${lead.razao}` : ''}` : ''}`,
    `Telefone: ${lead.telefone} · E-mail: ${lead.email}`,
    `Perfil: ${lead.perfil} · Origem: ${origem}`,
    '',
    ...produtos.map((p) => `• ${linhaProduto(p)}`),
    `Total: ${num(metragemTotal)} m`,
    lead.mensagem ? `\nSobre a obra/pedido:\n${lead.mensagem}` : '',
  ].join('\n').trim();

  return {
    json: {
      valido: true,
      email: {
        assunto: `Nova cotação LP — ${lead.razao || lead.nome} · ${num(metragemTotal)} m${temAnalise ? ' · análise' : ''}`,
        replyTo: lead.email,
        html,
      },
      planilha: {
        'Data': agora,
        'Nome': lead.nome,
        'Tipo': lead.tipo,
        'CNPJ': lead.cnpj,
        'Razão social': lead.razao,
        'Cidade': lead.cidade,
        'Telefone': lead.telefone,
        'E-mail': lead.email,
        'Perfil': lead.perfil,
        'Produtos': produtos.map(linhaProduto).join('\n'),
        'Metragem total (m)': metragemTotal,
        'Análise comercial': temAnalise ? 'Sim' : 'Não',
        'Mensagem': lead.mensagem,
        'Origem': origem,
        'Página': lead.pagina,
        ...lead.utm,
      },
      crm: {
        nome: lead.nome,
        email: lead.email,
        telefone: lead.telefone,
        empresa: lead.razao,
        cnpj: lead.cnpj,
        cidade: lead.cidade,
        perfil: lead.perfil,
        origem,
        metragem_total_m: metragemTotal,
        analise_comercial: temAnalise,
        titulo: `Cotação LP — ${lead.razao || lead.nome}`,
        observacoes: resumo,
      },
    },
  };
});
